const datos = $input.first().json;

const pokemon1 = datos.pokemonA;
const pokemon2 = datos.pokemonB;

function obtenerStat(pokemon, nombre) {
  return pokemon.stats.find(
    item => item.stat.name === nombre
  ).base_stat;
}

function calcularPoder(pokemon) {
  const ataque = obtenerStat(pokemon, 'attack');
  const defensa = obtenerStat(pokemon, 'defense');
  const velocidad = obtenerStat(pokemon, 'speed');

  return ataque * 2 + defensa + velocidad;
}

const poder1 = calcularPoder(pokemon1);
const poder2 = calcularPoder(pokemon2);

let ganador = 'empate';

if (poder1 > poder2) {
  ganador = pokemon1.name;
} else if (poder2 > poder1) {
  ganador = pokemon2.name;
}

return [{
  json: {
    pokemon1: pokemon1.name,
    pokemon2: pokemon2.name,
    poder1,
    poder2,
    ganador,
    estilo: $('Preparar datos').first().json.estilo
  }
}];

