parameters.jsCode:
const respuesta = $input.first().json;
const batalla = $('Calcular batalla').first().json;

const datosA = $('Guardar Pokémon A').first().json.pokemonA;
const datosB = $('Guardar Pokémon B').first().json.pokemonB;

const narracion = respuesta.choices?.[0]?.message?.content
  || 'La narración no está disponible.';

const escapar = (valor) => String(valor ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;')
  .replace(/'/g, '&#39;');

const nombreA = escapar(datosA.name.toUpperCase());
const nombreB = escapar(datosB.name.toUpperCase());
const poderA = batalla.poder1;
const poderB = batalla.poder2;

const imagenA = escapar(
  datosA.sprites.other['official-artwork'].front_default
);

const imagenB = escapar(
  datosB.sprites.other['official-artwork'].front_default
);

const empate = batalla.ganador === 'empate';

const titulo = empate
  ? '¡EMPATE!'
  : '¡VICTORIA DE ' + batalla.ganador.toUpperCase() + '!';

const tarjeta = (nombre, poder, imagen, ganador) => `
  <article class="pokemon-card">
    <img src="${imagen}" alt="${nombre}">
    <h2>${nombre}</h2>
    <div class="power">${poder}</div>
    <small>PUNTOS DE PODER</small>
    <span class="status">
      ${empate ? 'EMPATE' : ganador ? '🏆 GANADOR' : 'CONTENDIENTE'}
    </span>
  </article>
`;

const urlNuevaBatalla = 'https://TU-INSTANCIA.n8n.cloud/form/TU-ID-DE-FORMULARIO';
const htmlResultado = `
<!DOCTYPE html>
<html lang="es">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Pokémon Battle Arena</title>
<style>
  * { box-sizing: border-box; }

  body {
    margin: 0;
    padding: 24px 12px;
    background: #101827;
    color: #f8fafc;
    font-family: Arial, sans-serif;
  }

  .container {
    max-width: 760px;
    margin: auto;
  }

  header {
    text-align: center;
    margin-bottom: 24px;
  }

  .eyebrow {
    color: #93c5fd;
    letter-spacing: 3px;
    font-size: 12px;
  }

  h1 { font-size: 30px; margin: 10px 0; }

  .arena {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 16px;
  }

  .pokemon-card {
    text-align: center;
    background: #202d43;
    border: 1px solid #40516c;
    border-radius: 18px;
    padding: 18px 10px;
  }

  .pokemon-card img {
    width: 100%;
    max-width: 180px;
    height: 175px;
    object-fit: contain;
  }

  .pokemon-card h2 { font-size: 19px; }

  .power {
    font-size: 38px;
    font-weight: bold;
    color: #facc15;
  }

  small { color: #cbd5e1; }

  .status {
    display: block;
    margin: 15px auto 0;
    padding: 9px;
    border-radius: 12px;
    background: #334155;
    font-size: 12px;
    font-weight: bold;
  }

  .result, .story {
    background: #202d43;
    border-radius: 18px;
    padding: 22px;
    margin-top: 20px;
  }

  .result { text-align: center; }

  .result h2 { color: #facc15; }

  .story h2 { color: #93c5fd; }

  .story p {
    line-height: 1.8;
    white-space: pre-wrap;
  }

  @media(max-width: 420px) {
    h1 { font-size: 23px; }
    .arena { gap: 8px; }
    .pokemon-card img { height: 120px; }
    .pokemon-card h2 { font-size: 15px; }
  }


  .new-battle {
    display: block;
    margin: 26px auto;
    padding: 17px 24px;
    max-width: 360px;
    background: #facc15;
    color: #172033;
    border-radius: 14px;
    text-align: center;
    text-decoration: none;
    font-size: 16px;
    font-weight: bold;
    transition: background 0.2s;
  }

  .new-battle:hover {
    background: #fde68a;
  }

  .new-battle:focus-visible {
    outline: 3px solid #93c5fd;
    outline-offset: 4px;
  }

</style>
</head>
<body>
<main class="container">
  <header>
    <div class="eyebrow">POKÉMON BATTLE ARENA</div>
    <h1>⚔️ Batalla finalizada</h1>
    <p>Simulador impulsado por IA</p>
  </header>

  <section class="arena">
    ${tarjeta(nombreA, poderA, imagenA,
      batalla.ganador === datosA.name)}
    ${tarjeta(nombreB, poderB, imagenB,
      batalla.ganador === datosB.name)}
  </section>

  <section class="result">
    <h2>${escapar(titulo)}</h2>
    <p>${poderA} vs. ${poderB}</p>
  </section>

  <section class="story">
    <h2>📖 Narración de la batalla</h2>
    <p>${escapar(narracion)}</p>
  </section>

  <a href="${escapar(urlNuevaBatalla)}"
     class="new-battle">
    ⚔️ NUEVA BATALLA
  </a>

</main>
</body>
</html>
`;

return [{
  json: {
    ...batalla,
    narracion,
    titulo,
    htmlResultado
  }
}];

